document.addEventListener('DOMContentLoaded',()=>{
  const uaeday=document.getElementById('uaeday'),uaedate=document.getElementById('uaedate'),cards=document.getElementById('cards'),planlink=document.getElementById('planlink'),screenmode=document.getElementById('screenmode');
  const now=new Date();
  uaeday.textContent=new Intl.DateTimeFormat('en-GB',{weekday:'long',timeZone:'Asia/Dubai'}).format(now);
  uaedate.textContent=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dubai'}).format(now);

  const activities=[
    {n:1,title:'Picture Brainstorm',mode:'PAIR WORK',page:'9',mins:5,objective:'Brainstorm ideas and feelings from housing pictures.',keywords:['brainstorm','housing','independent','outdoors','feelings'],instruction:'Open page 9. Study each picture and brainstorm words, phrases and feelings with your partner.',images:['activity-1-brainstorm.png'],labels:['Book Activity 1 · Page 9'],bookAnswers:[['Picture 1: moving away · family support · independence','Picture 2: freedom · adventure · nature · challenge']],steps:['Study both pictures silently.','Describe what is happening.','Give three words or feelings for each picture.','Share one idea with the class.'],questions:[['What might picture 1 represent?','Moving away, family support, independence or a new beginning.'],['What might picture 2 represent?','Freedom, adventure, nature or possible discomfort.']]},
    {n:2,title:'Collocations: Learn & Compare',mode:'PAIR CHALLENGE',page:'10',mins:8,objective:'Recognize and use natural word partnerships.',keywords:['collocation','save money','get a degree','keep clean','have fun'],instruction:'A collocation is two or more words that commonly go together and sound natural, such as “save money.” Complete the new language challenge, then compare your ideas with Activity 2 on page 10.',images:['activity-2-vocabulary.png'],labels:['Book Activity 2 · Page 10'],bookAnswers:[['Possible comparison: save money · get a degree · keep clean · have fun']],steps:['Learn the meaning from the example “save money.”','Complete the new questions beside the book picture.','Reveal one answer at a time.','Compare the language with Activity 2.'],special:'collocations'},
    {n:3,title:'Campus Living: Pros & Cons',mode:'GROUP WORK',page:'10',mins:8,objective:'Sort campus-living benefits and challenges.',keywords:['campus accommodation','facilities','communication','shared living','pros','cons'],instruction:'Study the four girls-only situations first. Then open the book chart as a separate part and complete Activity 3.',images:['campus-pros-cons-mixed.png','activity-3-campus-chart.png'],labels:['Picture Challenge · Girls on Campus','Book Activity 3 · Page 10'],bookAnswers:[null,['Accommodation: + close to class / − limited space','Facilities: + convenient / − crowded','Communication: + support / − conflict','Shared living: + teamwork / − less privacy']],steps:['Name the situation in each numbered picture.','Sort pictures 1–2 as challenges and 3–4 as benefits.','Explain one reason for each choice.','Move to Part 2 and complete the book chart.'],questions:[['Which pictures show challenges?','Pictures 1 and 2: noise and homesickness.'],['Which pictures show benefits?','Pictures 3 and 4: making new friends and working together.']],special:'proscons'},
    {n:4,title:'Read, Highlight & Analyse',mode:'INDIVIDUAL → PAIR',page:'10–11',mins:18,objective:'Find vocabulary, main ideas and key details.',keywords:['unique housing','save money','privacy','security','loneliness','evidence'],instruction:'Read one section at a time. Highlight new vocabulary, state the main idea and find two supporting details.',images:['reading-introduction.png','reading-student-1.png','reading-student-2.png','reading-student-3a.png','reading-student-3b.png'],labels:['Introduction · Page 10','Student 1 · Page 10','Student 2 · Page 11','Student 3 · Part A','Student 3 · Part B'],steps:['Preview the title and predict the housing choices.','Read and highlight unfamiliar words.','State each section’s main idea.','Find two supporting details.','Compare answers using evidence.'],special:'reading'},
    {n:5,title:'Campus Crossword Race',mode:'TEAM GAME',page:'EXIT',mins:6,objective:'Review key language and reading ideas.',keywords:['collocation','evidence','privacy','lonely','unique housing'],instruction:'Solve five crossword clues as teams. Reveal one word at a time and award a point to the correct team.',images:[],steps:['Choose up to six teams.','Read the highlighted clue.','Agree on the crossword word.','Reveal it and award one point.','Complete all five clues.'],special:'exit'}
  ];

  cards.innerHTML=activities.map(a=>`<button class="card" data-num="${a.n}" onclick="openActivity(${a.n})"><span class="pill">${a.mode}</span><h3>${a.title}</h3><p>${a.objective}</p><span class="page">${a.page==='EXIT'?'EXIT TICKET':'BOOK PAGE '+a.page} · ${a.mins} MIN</span></button>`).join('');
  activities.forEach(a=>document.getElementById('activities').insertAdjacentHTML('beforeend',activityHTML(a)));
  activities.filter(a=>a.images.length).forEach(a=>moveBookPart(a.n,0));
  activities.forEach(a=>initTimer(document.querySelector(`#a${a.n} .timer`),a.mins*60));
  initSpecials();
  planlink.onclick=()=>openPlan(activities);

  screenmode.onclick=toggleFullScreen;
  document.addEventListener('fullscreenchange',()=>{const active=!!document.fullscreenElement;screenmode.hidden=active;document.querySelectorAll('.activityfullscreen').forEach(b=>b.hidden=active)});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeZoom();document.querySelectorAll('.activity.open').forEach(x=>x.classList.remove('open'));document.body.style.overflow=''}});
});

const zoom=document.getElementById('zoom');

function activityHTML(a){
  const book=a.images.length?`<div class="bookview separated" data-current="0"><div class="bookpartbar"><button onclick="moveBookPart(${a.n},-1)">← Previous Part</button><b>${a.labels?.[0]||'Book Part 1'}</b><span>1 of ${a.images.length}</span><button onclick="moveBookPart(${a.n},1)">Next Part →</button></div>${a.images.map((src,i)=>`<div class="bookcrop ${i===0?'current':''}" data-label="${a.labels?.[i]||`Book Part ${i+1}`}"><img src="assets/${src}" alt="${a.title} reference ${i+1}" onclick="openZoom(${a.n},${i})"><div class="marklayer"></div>${a.bookAnswers?.[i]?`<div class="bookanswers">${a.bookAnswers[i].map(x=>`<div>${x}</div>`).join('')}</div>`:''}</div>`).join('')}<span class="zoomhint">Click the picture to maximize ⛶</span></div>`:`<div class="gamevisual"><div class="trail">START <span>→</span> WORDS <span>→</span> TEXT <span>→</span> DECIDE</div><div class="trophy">🏡</div></div>`;
  const lessonmeta=a.n>=6?'Reading 2 · Part 2 · Pages 12–13':'Reading 2 · Part 1 · Pages 9–11';
  return `<section class="activity" id="a${a.n}"><header class="activitybar"><div class="activityidentity"><img src="assets/book-title.png" alt="Reading 2 title"><div><b>Grade 10 General</b> · Teacher Saidah Khwar<br>${lessonmeta} · ${document.getElementById('uaeday').textContent} · ${document.getElementById('uaedate').textContent}</div></div><div class="navgroup"><button onclick="moveActivity(${a.n},-1)">← Previous</button><button onclick="closeActivity(${a.n})">All Activities</button><button onclick="moveActivity(${a.n},1)">Next →</button></div><div class="boardtools">${a.images.length?'<button class="highlight" onclick="toggleHighlight('+a.n+')">🖍 Highlight Words</button><button onclick="clearMarks('+a.n+')">Clear Marks</button>':''}${a.bookAnswers?.some(Boolean)?'<button class="bookreveal" onclick="toggleBookAnswers('+a.n+')">Reveal on Book</button>':''}<button class="activityfullscreen" onclick="toggleFullScreen()">⛶ Full Screen</button></div><div class="timer"><span class="time">${String(a.mins).padStart(2,'0')}:00</span><button class="start">Start</button><button class="pause">Pause</button><button class="reset">Reset</button></div></header><div class="activitymain">${book}<div class="task"><div class="guide"><div class="taskkeywords"><b>KEY WORDS</b>${a.keywords.map(x=>`<span>${x}</span>`).join('')}</div><div class="taskhead"><small>ACTIVITY OBJECTIVE</small><h3>${a.objective}</h3></div><div class="instruction"><b>Students — what to do:</b><br>${a.instruction}</div></div><div class="steps">${a.steps.map((s,i)=>`<div class="step"><span>${i+1}</span><p>${s}</p></div>`).join('')}</div><div class="special" data-kind="${a.special||'questions'}">${a.questions?questionHTML(a.questions):''}</div></div></div></section>`;
}

async function toggleFullScreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch(e){document.querySelectorAll('.activityfullscreen').forEach(b=>b.textContent='Press F11') ;const main=document.getElementById('screenmode');if(main)main.textContent='Press F11 for Full Screen'}}

function moveBookPart(n,d){const v=document.querySelector(`#a${n} .bookview`),parts=[...v.querySelectorAll('.bookcrop')];let i=Math.max(0,Math.min(parts.length-1,+v.dataset.current+d));v.dataset.current=i;parts.forEach((p,j)=>p.classList.toggle('current',j===i));const b=v.querySelector('.bookpartbar');b.querySelector('b').textContent=parts[i].dataset.label;b.querySelector('span').textContent=`${i+1} of ${parts.length}`;b.querySelectorAll('button')[0].disabled=i===0;b.querySelectorAll('button')[1].disabled=i===parts.length-1;const s=document.getElementById('a'+n),r=s.querySelector('.bookreveal'),ink=parts[i].querySelector('.bookanswers');s.classList.remove('showbookanswers');s.querySelectorAll('.bookanswers div').forEach(x=>x.classList.remove('revealed'));if(r){r.disabled=!ink;r.textContent=ink?'Reveal Answer 1':'No Answers on This Part'}}
function toggleBookAnswers(n){const s=document.getElementById('a'+n),b=s.querySelector('.bookreveal'),box=s.querySelector('.bookcrop.current .bookanswers');if(!box)return;const items=[...box.children],next=items.find(x=>!x.classList.contains('revealed'));if(!s.classList.contains('showbookanswers')){s.classList.add('showbookanswers');items[0]?.classList.add('revealed');b.textContent=items.length>1?'Reveal Answer 2':'Hide Book Answer';return}if(next){next.classList.add('revealed');const left=items.filter(x=>!x.classList.contains('revealed')).length;b.textContent=left?`Reveal Answer ${items.length-left+1}`:'Hide Book Answers'}else{s.classList.remove('showbookanswers');items.forEach(x=>x.classList.remove('revealed'));b.textContent='Reveal Answer 1'}}

function questionHTML(qs){return qs.map((q,i)=>`<div class="question"><b>${i+1}. ${q[0]}</b><button class="reveal">Reveal Answer</button><div class="answer">${q[1]}</div></div>`).join('')}
function openActivity(n){document.querySelectorAll('.activity.open').forEach(x=>x.classList.remove('open'));document.getElementById('a'+n).classList.add('open');document.body.style.overflow='hidden'}
function closeActivity(n){document.getElementById('a'+n).classList.remove('open');document.body.style.overflow=''}
function moveActivity(n,d){const first=n<=5?1:6,last=n<=5?5:10,next=n+d;if(next<first||next>last){closeActivity(n);return}openActivity(next)}

function bindReveals(root=document){root.querySelectorAll('.reveal').forEach(b=>b.onclick=()=>{const a=b.nextElementSibling;a.classList.toggle('show');b.textContent=a.classList.contains('show')?'Hide Answer':'Reveal Answer'})}
function initTimer(t,total){let left=total,id=null;const d=t.querySelector('.time'),paint=()=>d.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');t.querySelector('.start').onclick=()=>{if(id)return;id=setInterval(()=>{if(left){left--;paint()}else{clearInterval(id);id=null;d.textContent='TIME!'}},1000)};t.querySelector('.pause').onclick=()=>{clearInterval(id);id=null};t.querySelector('.reset').onclick=()=>{clearInterval(id);id=null;left=total;paint()}}

function initSpecials(){
  bindReveals();
  const checks=[['Which sounds natural: make a degree or get a degree?','get a degree'],['Correct the phrase: “do money.”','save money or make money'],['Complete: Good roommates ___ together.','have fun'],['Choose the natural phrase: keep clean or stay a clean?','keep clean'],['Create one sentence using a collocation.','Example: I want to save money for university.']];
  const c=document.querySelector('#a2 .special');c.innerHTML=`<h2>Collocation Check</h2><p class="collocationexplain"><b>Meaning:</b> A collocation is a pair or group of words that usually go together and sound natural. Example: <strong>save money</strong>.</p>${questionHTML(checks)}`;bindReveals(c);
  const p=document.querySelector('#a3 .special');p.insertAdjacentHTML('afterbegin','<div class="classify"><b>Choose before revealing:</b><span>Benefits: ___ and ___</span><span>Challenges: ___ and ___</span></div>');
  const r=document.querySelector('#a4 .special');r.innerHTML=`<aside class="deepchallenge"><button class="challengereveal">★ Reveal Deep Thinking Challenge</button><p>Which student made the wisest housing choice—not simply the cheapest one? Use evidence from the article, then suggest one change that would make that student’s life healthier or happier.</p></aside><div class="readingnote"><b>Maximize each paragraph</b><span>Three comprehension questions will appear beside the text without covering it.</span></div>`;r.querySelector('.challengereveal').onclick=e=>{const box=e.currentTarget.parentElement,open=box.classList.toggle('show');e.currentTarget.textContent=open?'★ Hide Deep Thinking Challenge':'★ Reveal Deep Thinking Challenge'};
  initExit();initMarkers();
}

const readingChecks=[
  [['What is the main idea of the introduction?','The article presents three students who saved money by living in unusual ways.'],['Which three common housing choices are named?','Dormitories, apartments and parents’ homes.'],['What does endured suggest?','They experienced and continued through difficulties.']],
  [['What is the main idea of Joe’s account?','Joe saved a large amount of money by living on a sailboat.'],['Give two details showing how he reduced costs.','He paid $1.50 per day to tie the boat and used a bicycle and found wood.'],['Why were people fascinated?','They found earning a degree while living on a boat unusual and surprising.']],
  [['What is the main idea of Frank’s account?','Frank saved money and became known online while living in a tent.'],['What were his two main concerns?','Privacy and security.'],['What does “I’m to blame” mean?','He accepts responsibility because broadcasting his life attracted visitors.']],
  [['What is the main idea of Ken’s account?','Ken avoided major housing costs by living secretly in a van.'],['How did he access showers, Internet and electricity?','He used a gym membership and the university library.'],['How much did he estimate students could save?','Almost $9,000 over four years.']],
  [['What was the greatest cost of Ken’s choice?','Loneliness and missing close relationships.'],['Why did he “live a lie”?','He was not supposed to live in the van and had to hide it.'],['What lesson does his experience add to the article?','Saving money may create serious social and emotional costs.']]
];

function openZoom(activity,index){
  const section=document.getElementById('a'+activity),crop=section.querySelectorAll('.bookcrop')[index],src=crop.querySelector('img').src,answers=activity===4?readingChecks[index]:null,ink=crop.querySelector('.bookanswers');
  zoom.innerHTML=`<div class="zoomstage ${answers?'withcheck':''}"><div class="zoomimage"><img src="${src}" alt="Maximized activity"><div class="zoommarks"></div>${ink?`<div class="bookanswers zoombookanswers">${ink.innerHTML}</div>`:''}</div>${answers?`<aside class="zoomcheck"><small>READING CHECK</small><h2>Check Understanding</h2>${questionHTML(answers)}</aside>`:''}</div><div class="zoomtools">${ink?'<button class="zoomreveal">Reveal Answer 1</button>':''}<button class="zoomhighlight">🖍 Highlight</button><button class="zoomclear">Clear Marks</button><button class="zoomclose">Close ✕</button></div>`;
  zoom.classList.add('open');zoom.setAttribute('aria-hidden','false');bindReveals(zoom);wireCanvas(zoom.querySelector('.zoommarks'),zoom.querySelector('.zoomhighlight'));zoom.querySelector('.zoomclear').onclick=()=>zoom.querySelectorAll('.markerstroke').forEach(x=>x.remove());zoom.querySelector('.zoomclose').onclick=closeZoom;if(ink){const box=zoom.querySelector('.zoombookanswers'),button=zoom.querySelector('.zoomreveal'),items=[...box.children];items.forEach(x=>x.classList.remove('revealed'));button.onclick=()=>{const next=items.find(x=>!x.classList.contains('revealed'));if(!box.classList.contains('active')){box.classList.add('active');items[0]?.classList.add('revealed');button.textContent=items.length>1?'Reveal Answer 2':'Hide Answer'}else if(next){next.classList.add('revealed');const left=items.filter(x=>!x.classList.contains('revealed')).length;button.textContent=left?`Reveal Answer ${items.length-left+1}`:'Hide Answers'}else{box.classList.remove('active');items.forEach(x=>x.classList.remove('revealed'));button.textContent='Reveal Answer 1'}}}
}
function closeZoom(){zoom.classList.remove('open');zoom.setAttribute('aria-hidden','true');zoom.innerHTML=''}
function initMarkers(){document.querySelectorAll('.marklayer').forEach(layer=>wireCanvas(layer))}
function wireCanvas(layer,button){let active=false,startX=0,startY=0,mark=null;if(!button){layer.dataset.ready='1';return}button.onclick=()=>{active=!active;layer.classList.toggle('active',active);button.classList.toggle('active',active);button.textContent=active?'✓ Highlighter On':'🖍 Highlight'};layer.onpointerdown=e=>{if(!active&&!layer.classList.contains('active'))return;e.preventDefault();const r=layer.getBoundingClientRect();startX=e.clientX-r.left;startY=e.clientY-r.top;mark=document.createElement('i');mark.className='markerstroke';layer.appendChild(mark)};layer.onpointermove=e=>{if(!mark)return;const r=layer.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;Object.assign(mark.style,{left:Math.min(startX,x)+'px',top:Math.min(startY,y)+'px',width:Math.max(8,Math.abs(x-startX))+'px',height:Math.max(14,Math.abs(y-startY))+'px'})};layer.onpointerup=layer.onpointercancel=()=>mark=null}
function toggleHighlight(n){const s=document.getElementById('a'+n),b=s.querySelector('.highlight'),on=!b.classList.contains('active');b.classList.toggle('active',on);b.textContent=on?'✓ Highlighter On':'🖍 Highlight Words';s.querySelectorAll('.marklayer').forEach(x=>{x.classList.toggle('active',on);if(on&&!x.onpointerdown){let sx=0,sy=0,m=null;x.onpointerdown=e=>{const r=x.getBoundingClientRect();sx=e.clientX-r.left;sy=e.clientY-r.top;m=document.createElement('i');m.className='markerstroke';x.appendChild(m)};x.onpointermove=e=>{if(!m)return;const r=x.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;Object.assign(m.style,{left:Math.min(sx,px)+'px',top:Math.min(sy,py)+'px',width:Math.max(8,Math.abs(px-sx))+'px',height:Math.max(14,Math.abs(py-sy))+'px'})};x.onpointerup=x.onpointercancel=()=>m=null}})}
function clearMarks(n){document.querySelectorAll(`#a${n} .markerstroke`).forEach(x=>x.remove())}

function initExit(){
  const s=document.querySelector('#a5 .special'),words=[
    {word:'MONEY',clue:'Complete the collocation: save ___.',row:1,col:8,dir:'v'},
    {word:'LONELY',clue:'How did Ken feel because he kept his van life secret?',row:2,col:7,dir:'h'},
    {word:'EVIDENCE',clue:'What should readers use to support an answer?',row:2,col:10,dir:'v'},
    {word:'BOAT',clue:'Where did Joe live while earning his degree?',row:3,col:6,dir:'v'},
    {word:'PRIVACY',clue:'One concern Frank had while living in a tent.',row:5,col:2,dir:'h'}
  ];let i=0;const cells=new Map();words.forEach((w,wi)=>[...w.word].forEach((letter,j)=>{const r=w.row+(w.dir==='v'?j:0),c=w.col+(w.dir==='h'?j:0),key=`${r}-${c}`;if(!cells.has(key))cells.set(key,{letter,words:[]});cells.get(key).words.push(wi)}));
  const grid=Array.from({length:9},(_,r)=>Array.from({length:12},(_,c)=>{const key=`${r+1}-${c+1}`,cell=cells.get(key);return cell?`<span class="crosscell" data-words="${cell.words.join(' ')}" data-letter="${cell.letter}"></span>`:'<span class="crosscell blocked"></span>'}).join('')).join('');
  s.innerHTML=`<div class="crosswordgame"><header><div><small>GROUP CHALLENGE · 5 CLUES</small><h2>Campus Crossword Race</h2></div><div class="teamscores">${[1,2,3,4,5,6].map(n=>`<button data-team="${n}">Team ${n}: <b>0</b></button>`).join('')}</div></header><div class="crosslayout"><div class="crossgrid">${grid}</div><div class="crossclue"><div class="counter">Clue <span>1</span> of 5</div><h3></h3><button class="reveal">Reveal Word</button><div class="answer"></div><div class="gamenav"><button class="prev">← Previous</button><button class="next">Next →</button><button class="restart">Restart ↻</button></div></div></div></div>`;
  const draw=()=>{s.querySelector('.counter span').textContent=i+1;s.querySelector('.crossclue h3').textContent=words[i].clue;s.querySelector('.answer').textContent=words[i].word;s.querySelector('.answer').classList.remove('show');s.querySelector('.reveal').textContent='Reveal Word';s.querySelector('.prev').disabled=i===0;s.querySelector('.next').disabled=i===words.length-1;s.querySelectorAll('.crosscell').forEach(x=>x.classList.toggle('activeword',x.dataset.words?.split(' ').includes(String(i))))};
  s.querySelector('.reveal').onclick=e=>{const a=e.currentTarget.nextElementSibling,show=!a.classList.contains('show');a.classList.toggle('show',show);e.currentTarget.textContent=show?'Hide Word':'Reveal Word';s.querySelectorAll('.crosscell').forEach(x=>{if(x.dataset.words?.split(' ').includes(String(i))){x.textContent=show?x.dataset.letter:'';x.classList.toggle('solved',show)}})};s.querySelector('.prev').onclick=()=>{if(i){i--;draw()}};s.querySelector('.next').onclick=()=>{if(i<words.length-1){i++;draw()}};s.querySelectorAll('.teamscores button').forEach(b=>b.onclick=()=>{b.querySelector('b').textContent=+b.querySelector('b').textContent+1});s.querySelector('.restart').onclick=()=>{i=0;s.querySelectorAll('.crosscell:not(.blocked)').forEach(x=>{x.textContent='';x.classList.remove('solved')});s.querySelectorAll('.teamscores b').forEach(x=>x.textContent='0');draw()};
  const canvas=document.querySelector('#a5 .gamevisual');canvas.innerHTML='';canvas.className='activitycanvas';canvas.appendChild(s);draw();
}

function openPlan(A){
  document.getElementById('liveplan')?.remove();
  const clean=s=>(s||'').replace(/\s+/g,' ').trim(),link='https://saidahkhwar11-lang.github.io/Interactive-English-Lessons/Term-1/Grade-10/dist/';
  const objectives=[...document.querySelectorAll('.part1only.objectives .objectivegrid p')].map(x=>clean(x.textContent));
  const keywords=[...document.querySelectorAll('.part1only.objectives .keywords span')].map(x=>clean(x.textContent));
  const data=A.map(a=>({title:a.title,badge:(a.page==='EXIT'?'EXIT TICKET':'BOOK PAGE '+a.page)+' · '+a.mins+' MIN',mode:a.mode,objective:a.objective,instruction:a.instruction,steps:a.steps,challenge:a.n===4?'Which housing choice best balances money, safety and wellbeing? Use text evidence, then redesign one part of it for a student like you.':''}));
  const block=a=>`<article class="schoolactivity"><h3>${a.title} <em>${a.badge}</em></h3><p><b>Type:</b> ${a.mode}</p><p><b>Procedure:</b> ${a.instruction}</p><ol>${a.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${a.challenge?`<p><b>Deep Thinking Challenge:</b> ${a.challenge}</p>`:''}<p><b>Teacher’s Role:</b> Display, guide, question, monitor and give feedback.</p><p><b>Students’ Role:</b> Complete the task, discuss ideas and justify answers.</p><p><b>Purpose:</b> ${a.objective}</p></article>`;
  const starter=data[0],plenary=data[data.length-1],main=data.slice(1,-1),modal=document.createElement('section');
  modal.id='liveplan';modal.className='liveplan schoolplan';modal.innerHTML=`<div class="plancontrols"><button class="planprint">Print / Save PDF</button><button class="planclose">Close ✕</button></div><div class="schoolpage"><div class="academicyear"><span>العام الأكاديمي</span><b>2026–2027</b></div><table class="schooltable details"><tr><th>التاريخ<br>Date:</th><td>${document.getElementById('uaeday').textContent} · ${document.getElementById('uaedate').textContent}</td><th>المادة الدراسية<br>Subject</th><td>English</td><th>المعلم<br>Teacher(s)</th><td>Saidah Khwar</td><th>عنوان الدرس<br>Lesson #</th><td>Reading 2 · Unique Housing</td></tr><tr><th>موضوع الدرس<br>Lesson Topic</th><td colspan="2"><b class="plantopictitle">Unique Housing for Three College Students</b><br><a class="lessonlink" href="${link}" target="_blank" rel="noopener">Open Interactive Lesson ↗</a></td><th>مخرجات التعلم<br>Key Learning Objective(s)</th><td colspan="4"><ul>${objectives.map(x=>`<li>Students will be able to ${x.charAt(0).toLowerCase()+x.slice(1)}</li>`).join('')}</ul></td></tr><tr><th>سؤال مهارات التفكير العليا<br>H.O.T. Question(s)</th><td colspan="7">Which housing choice best balances money, safety and wellbeing? Use text evidence, then redesign one part of it for a student like you.</td></tr><tr><th>المفردات الجديدة<br>Keywords/New Vocabulary</th><td colspan="7">${keywords.join(' · ')}</td></tr><tr class="sectionrow"><th colspan="8">Lesson’s Procedures · سير الدرس</th></tr><tr><th>معايير النجاح<br>Success Criteria</th><td colspan="7">By the end of the lesson, ${clean(document.querySelector('.criteria')?.textContent)}</td></tr></table></div><div class="schoolpage"><div class="academicyear"><span>العام الأكاديمي</span><b>2026–2027</b></div><table class="schooltable procedures"><tr><th class="stage">التهيئة الحافزة<br>Warm up/Starter</th><td colspan="4">${block(starter)}</td><td class="timing">${starter.badge.match(/\d+ MIN/)?.[0].toLowerCase()}</td></tr><tr><th>التطبيق الإلكتروني المستخدم<br>E-Implementation Tool</th><th class="level"></th><th>الفروق الفردية<br>Differentiation</th><th colspan="2">الاستراتيجيات المستخدمة لتحقيق مخرج التعلم<br>Main Activities linked to LO · AFL Strategy</th><th>التوقيت<br>Timing</th></tr><tr><td rowspan="3">Interactive lesson webpage<br>DataShow / Smart Board</td><td class="high">H</td><td><b>High:</b> Infer vocabulary and evaluate housing choices independently using several text details.</td><td rowspan="3" colspan="2" class="mainactivities"><h3>Main Activities</h3>${main.map(block).join('')}</td><td rowspan="3">Flexible within the 45-minute lesson</td></tr><tr><td class="medium">M</td><td><b>Medium:</b> Use pair discussion, question prompts and sentence starters.</td></tr><tr><td class="low">L</td><td><b>Low:</b> Use clear book parts, visuals, highlighted words and guided answer reveals.</td></tr><tr><th>الختام<br>Plenary</th><td colspan="4">${block(plenary)}</td><td class="timing">${plenary.badge.match(/\d+ MIN/)?.[0].toLowerCase()}</td></tr><tr><th colspan="2">متعلمون مستقلون<br>Independent Learners</th><td colspan="2"><b class="skillhit">Critical Thinking</b> · Self-Learning · <b class="skillhit">Clear Communication</b> · Positive Interactions · Research · <b class="skillhit">Collaboration</b> · Real World Connections · Innovation</td><th colspan="2">Learning Skills (please highlight)</th></tr><tr><th colspan="2">ربط مع مواد أخرى<br>Cross Curricular</th><td colspan="4"><b>Financial Literacy / Wellbeing:</b> Balance cost, security, privacy, independence and relationships.</td></tr><tr><th colspan="2">تعزيز ثقافة دولة الإمارات العربية المتحدة<br>UAE Culture and Heritage (UAE Vision 2031)</th><td colspan="4">Promotes responsible decision-making, innovation, wellbeing and cooperation in a diverse UAE community.</td></tr></table><footer>Lesson Plan · Generated automatically from the current live lesson</footer></div>`;
  document.body.appendChild(modal);document.body.style.overflow='hidden';modal.querySelector('.planclose').onclick=()=>{modal.remove();document.body.style.overflow=''};modal.querySelector('.planprint').onclick=()=>window.print();
}
